/**
 * SDK drift check.
 *
 * `packages/sdk/src/openapi.ts` is the contract. This script reads it and
 * regenerates `packages/sdk/generated/routes.ts`, a flat table of the declared
 * paths, methods and operation ids. The generated file is committed, so if the
 * contract changes and this is not re-run, CI's git-diff check fails.
 *
 * Usage: `bun scripts/generate-sdk.ts [--check]`
 */
import { writeFileSync, mkdirSync, existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

const ROOT = resolve(import.meta.dir, "..");
const SPEC = resolve(ROOT, "packages/sdk/src/openapi.ts");
const OUT = resolve(ROOT, "packages/sdk/generated/routes.ts");

interface Route {
  readonly path: string;
  readonly method: string;
  readonly operationId: string;
  readonly summary: string;
  readonly tags: readonly string[];
}

function main(): void {
  if (!existsSync(SPEC)) {
    process.stderr.write(`! missing ${SPEC}\n`);
    process.exit(1);
  }
  const source = readSpec();

  const routes: Route[] = [];
  const pathBlock = /paths:\s*\{([\s\S]*?)\n {2}\},/;
  const match = source.match(pathBlock);
  if (!match?.[1]) {
    process.stderr.write("! could not locate the paths block in openapi.ts\n");
    process.exit(1);
  }
  const body = match[1];

  const pathRe = /^\s{4}"([^"]+)":\s*\{$/gm;
  let pm: RegExpExecArray | null;
  const paths: { path: string; at: number }[] = [];
  while ((pm = pathRe.exec(body)) !== null) {
    if (pm[1]) paths.push({ path: pm[1], at: pm.index });
  }

  for (let i = 0; i < paths.length; i += 1) {
    const current = paths[i];
    const next = paths[i + 1];
    const start = current!.at;
    const end = next ? next.at : body.length;
    const chunk = body.slice(start, end);
    const methodRe = /\b(get|post|put|patch|delete):\s*\{/g;
    let mm: RegExpExecArray | null;
    while ((mm = methodRe.exec(chunk)) !== null) {
      const methodStart = mm.index;
      const methodChunk = chunk.slice(methodStart, methodStart + 2000);
      const opId = methodChunk.match(/operationId:\s*"([^"]+)"/)?.[1];
      const summary = methodChunk.match(/summary:\s*"([^"]+)"/)?.[1] ?? "";
      const tags = [...methodChunk.matchAll(/tags:\s*\["([^"]+)"\]/g)].map((m) => m[1] ?? "");
      if (!opId) continue;
      routes.push({
        path: current!.path,
        method: (mm[1] ?? "get").toUpperCase(),
        operationId: opId,
        summary,
        tags
      });
    }
  }

  const output = `/**
 * GENERATED by scripts/generate-sdk.ts — do not edit by hand.
 *
 * A flat view of the OpenAPI contract. Regenerate with
 * \`bun scripts/generate-sdk.ts\`; CI fails if this file is stale.
 */

export interface RouteRow {
  readonly path: string;
  readonly method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  readonly operationId: string;
  readonly summary: string;
  readonly tags: readonly string[];
}

export const ROUTES: readonly RouteRow[] = [
${routes.map((r) => `  { path: ${JSON.stringify(r.path)}, method: ${JSON.stringify(r.method)}, operationId: ${JSON.stringify(r.operationId)}, summary: ${JSON.stringify(r.summary)}, tags: ${JSON.stringify(r.tags)} }`).join(",\n")}
];

export const ROUTE_COUNT = ROUTES.length;

export function route(method: string, path: string): RouteRow | undefined {
  return ROUTES.find((r) => r.method === method.toUpperCase() && r.path === path);
}
`;

  if (process.argv.includes("--check")) {
    if (!existsSync(OUT)) {
      process.stderr.write(`! ${OUT} is missing — run bun scripts/generate-sdk.ts\n`);
      process.exit(1);
    }
    const existing = readFileSync(OUT, "utf8");
    if (existing !== output) {
      process.stderr.write(`! ${OUT} is stale — run bun scripts/generate-sdk.ts\n`);
      process.exit(1);
    }
    process.stdout.write(`sdk contract in sync: ${routes.length} routes\n`);
    return;
  }

  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, output, "utf8");
  process.stdout.write(`sdk routes generated: ${routes.length} -> ${resolve(ROOT, "packages/sdk/generated/routes.ts")}\n`);
}

function readSpec(): string {
  return readFileSync(SPEC, "utf8");
}

main();
